package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.ComplaintRequest;import com.example.riskplatform.entity.Complaint;import com.example.riskplatform.service.ComplaintService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/complaints") @RequiredArgsConstructor public class ComplaintController{private final ComplaintService s;@GetMapping @PreAuthorize("hasAuthority('complaint:read')")public ApiResponse<List<Complaint>>list(@RequestParam(required=false)Long companyId,@RequestParam(required=false)String category){return ApiResponse.ok(s.list(companyId,category));}@PostMapping @PreAuthorize("hasAuthority('complaint:write')")public ApiResponse<Complaint>create(@Valid @RequestBody ComplaintRequest r){return ApiResponse.ok(s.create(r));}}